create or replace function app.urws_asset_status_event_trigger() returns trigger language plpgsql security definer set search_path=public,app as $$ begin if new.status is not distinct from old.status then return new; end if; if lower(coalesce(new.status,'')) not in ('lost','damaged','missing','stolen','out_of_service') then return new; end if; insert into public.platform_event_outbox(tenant_id,event_type,aggregate_type,aggregate_id,payload,occurred_at,status) values(null,'assets.loss_or_damage','asset',new.id,jsonb_build_object('organization_id',new.organization_id,'asset_id',new.id,'asset_name',new.name,'asset_status',new.status),now(),'pending'); return new; end; $$;
drop trigger if exists urws_asset_status_event on public.assets;
create trigger urws_asset_status_event after update of status on public.assets for each row execute function app.urws_asset_status_event_trigger();
insert into public.urws_event_rules(organization_id,event_type,case_type_code,subject_type,priority,public_summary_template,origin_prefix,auto_open,active,conditions,metadata) values(null,'assets.loss_or_damage','equipment_loss_damage','asset','normal','Equipment loss or damage requires operational review.','asset-loss-damage',true,true,'{}'::jsonb,'{"bridge":"assets"}'::jsonb) on conflict (organization_id,event_type,case_type_code) do update set active=true,auto_open=true,metadata=excluded.metadata;
create table if not exists public.urws_record_corrections(id uuid primary key default gen_random_uuid(),tenant_id uuid,organization_id uuid not null,entity_type text not null,entity_id uuid not null,field_name text,reported_value jsonb,canonical_value jsonb,reason text not null,status text not null default 'requested' check(status in ('requested','reviewing','approved','rejected','applied')),requested_by_person_id uuid references public.people(id),requested_by_auth_user_id uuid,decided_by_person_id uuid references public.people(id),decided_at timestamptz,applied_at timestamptz,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table public.urws_record_corrections enable row level security;
drop policy if exists urws_record_corrections_superuser on public.urws_record_corrections; create policy urws_record_corrections_superuser on public.urws_record_corrections for all to authenticated using(app.is_superuser()) with check(app.is_superuser());
create or replace function app.urws_record_correction_event_trigger() returns trigger language plpgsql security definer set search_path=public,app as $$ begin if new.status<>'requested' then return new; end if; insert into public.platform_event_outbox(tenant_id,event_type,aggregate_type,aggregate_id,payload,occurred_at,status) values(new.tenant_id,'records.correction.requested','record_correction',new.id,jsonb_build_object('organization_id',new.organization_id,'entity_type',new.entity_type,'entity_id',new.entity_id,'correction_id',new.id),now(),'pending'); return new; end; $$;
drop trigger if exists urws_record_correction_event on public.urws_record_corrections; create trigger urws_record_correction_event after insert on public.urws_record_corrections for each row execute function app.urws_record_correction_event_trigger();
insert into public.urws_event_rules(organization_id,event_type,case_type_code,subject_type,priority,public_summary_template,origin_prefix,auto_open,active,conditions,metadata) values(null,'records.correction.requested','record_correction','record_correction','normal','Canonical record correction requires governed review.','record-correction',true,true,'{}'::jsonb,'{"bridge":"record_corrections"}'::jsonb) on conflict (organization_id,event_type,case_type_code) do update set active=true,auto_open=true,metadata=excluded.metadata;